func (c *Changes) RemoveIndex(indexes ...int) {
	// Create a set of indexes to remove for O(1) lookup
	toRemove := make(map[int]bool)
	for _, idx := range indexes {
		toRemove[idx] = true
	}

	// Move elements that aren't removed to the front of the slice
