		&MockChange{"1"},
		&MockChange{"2"},
		&MockChange{"3"},
		&MockChange{"4"},
	}

	fmt.Println("Original:", len(*changes), (*changes)[0], (*changes)[1], (*changes)[2], (*changes)[3], (*changes)[4])

